import pandas as pd
df = pd.read_csv('dataset/hospital_compensation_registry.csv', parse_dates=['record_date'])
d = df.set_index('patient_id', drop=False)
ec = d.emergency_contact_patient_id
indeg = ec.value_counts()
claimed = d.compensation_reason.notna()

def short(p):
    r = d.loc[p]
    if claimed[p]:
        return f"{p} {r.full_name:<15} {str(r.record_date.date())} ${r.direct_payment_usd:>9,.0f} {r.compensation_reason[:28]:<28} {r.coverage_status[:3]}/{r.documentation_status[:4]} in={indeg.get(p,0)}"
    return f"{p} {r.full_name:<15} {'NO CLAIM':<10} {'':>10} {'':<28} {'':8} in={indeg.get(p,0)}"

# Cycles in functional graph (each node has exactly one outgoing edge)
state = {}
cycles = []
for s in d.index:
    path = []
    cur = s
    while cur not in state:
        state[cur] = ('visiting', s)
        path.append(cur)
        cur = ec[cur]
    if state[cur][0] == 'visiting' and state[cur][1] == s:
        cyc = path[path.index(cur):]
        cycles.append(cyc)
    for p in path:
        state[p] = ('done', s)
print("cycles in EC graph:", cycles)

# union-find for weak components
parent = {p:p for p in d.index}
def find(x):
    while parent[x]!=x:
        parent[x]=parent[parent[x]]; x=parent[x]
    return x
for p,c in ec.items():
    parent[find(p)] = find(c)
from collections import Counter
sizes = Counter(find(p) for p in d.index)
print("weak component sizes:", sorted(sizes.values(), reverse=True))

big = ['PAT_265','PAT_033','PAT_006']
for b in big:
    print("="*115)
    print("CLAIMANT ", short(b), "| component size", sizes[find(b)])
    chain=[b]; seen={b}
    while True:
        n=ec[chain[-1]]
        if n in seen:
            chain.append(n+'(cycle)'); break
        chain.append(n); seen.add(n)
        if len(chain)>10: break
    print(" OUT CHAIN:", ' -> '.join(chain))
    for p in chain[1:5]:
        if p.endswith('(cycle)'): break
        print("    ", short(p))
    print(" IN (depth 1, with their in-neighbours):")
    for p in d.index[ec==b]:
        print("    ", short(p))
        for q in d.index[ec==p]:
            print("          <-", short(q))
EOF

