import pandas as pd
from collections import deque, defaultdict
df = pd.read_csv('dataset/hospital_compensation_registry.csv', parse_dates=['record_date'])
d = df.set_index('patient_id', drop=False)
ec = d.emergency_contact_patient_id.to_dict()
claimed = d.compensation_reason.notna().to_dict()
rev = defaultdict(list)
for p,c in ec.items(): rev[c].append(p)
S = {'PAT_265':'B1','PAT_033':'B2','PAT_006':'B3'}

def bfs(src, directed=None):
    dist={src:0}; q=deque([src])
    while q:
        u=q.popleft()
        nbrs=[]
        if directed in (None,'out'): nbrs.append(ec[u])
        if directed in (None,'in'): nbrs+=rev[u]
        for v in nbrs:
            if v not in dist:
                dist[v]=dist[u]+1; q.append(v)
    return dist

# undirected distances from each claimant to every unclaimed patient
dists = {s:bfs(s) for s in S}
rows=[]
for p in d.index:
    if not claimed[p]:
        rows.append((p, d.full_name[p], *(dists[s][p] for s in S)))
t = pd.DataFrame(rows, columns=['pid','name']+list(S.values()))
t['min']=t[list(S.values())].min(axis=1)
print("Unclaimed patients within 2 hops (undirected) of a claimant:")
print(t[t['min']<=2].sort_values('min').to_string(index=False))

# row positions in the file
print("\nRow positions in CSV for key IDs:")
pos = {p:i for i,p in enumerate(df.patient_id)}
for p in ['PAT_265','PAT_023','PAT_065','PAT_033','PAT_174','PAT_006','PAT_102','PAT_078','PAT_011']:
    print(p, d.full_name[p], 'row', pos[p])
