import csv
import json
from datetime import date

DATASET = "/app/dataset/hospital_compensation_registry.csv"

# Euphemistic claim reasons paid out at ~$100k (about 2x the next largest claim).
# The claimants are the bereaved relatives, not the deceased.
BEREAVEMENT_REASONS = {
    "bereavement compensation",
    "family support adjustment",
    "life event claim",
}


def answer() -> set[str]:
    with open(DATASET, newline="") as f:
        rows = list(csv.DictReader(f))

    claim_date = {
        r["patient_id"]: date.fromisoformat(r["record_date"]) if r["record_date"] else None
        for r in rows
    }

    deceased = set()
    for claim in rows:
        if claim["compensation_reason"] not in BEREAVEMENT_REASONS:
            continue
        bereaved = claim["patient_id"]
        # The deceased listed the claimant as their emergency contact. Anyone who
        # filed a claim after the bereavement claim was alive afterwards; whoever
        # has no later claim (none at all, or only an earlier one) is the deceased.
        for r in rows:
            if r["emergency_contact_patient_id"] != bereaved:
                continue
            filed = claim_date[r["patient_id"]]
            if filed is None or filed < claim_date[bereaved]:
                deceased.add(r["patient_id"])
    return deceased


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

